package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.phys.*;import net.minecraft.network.chat.Component;import java.util.*;
/** Normal BlockItem transactions retain loader multi-place/claim cancellation and item rollback. */
public final class Ps01Item extends BlockItem{
 public Ps01Item(Block b,Properties p){super(b,p);}
 public static net.minecraft.nbt.CompoundTag data(ItemStack s){return s.hasTag()?s.getTag().copy():new net.minecraft.nbt.CompoundTag();}
 public static void data(ItemStack s,net.minecraft.nbt.CompoundTag n){s.setTag(n);}
 public static Direction face(Player p,ItemStack item){var f=p==null?Direction.NORTH:p.getDirection().getOpposite();int q=data(item).getInt("PsRotation")&3;for(int i=0;i<q;i++)f=f.getClockWise();return f;}
 public static BlockPos anchor(BlockPos above,Direction f){return above.relative(f.getOpposite(),4);}
 @Override public InteractionResult useOn(UseOnContext c){if(c.getPlayer()!=null&&c.getPlayer().isShiftKeyDown()){var n=data(c.getItemInHand());n.putInt("PsRotation",(n.getInt("PsRotation")+1)&3);data(c.getItemInHand(),n);if(!c.getLevel().isClientSide)c.getPlayer().displayClientMessage(Component.literal("PS-01 preview rotated 90 degrees"),true);return InteractionResult.SUCCESS;}return super.useOn(c);}
 @Override public BlockPlaceContext updatePlacementContext(BlockPlaceContext c){if(c.getClickedFace()!=Direction.UP)return null;var f=face(c.getPlayer(),c.getItemInHand());var root=anchor(c.getClickedPos(),f);if(!BunkerVegetation.replaceable(c.getLevel(),root)){if(c.getPlayer()!=null)c.getPlayer().displayClientMessage(Component.literal("Blocked: clear the complete shelter area"),true);return null;}return BunkerVegetation.at(c,root);}
 public static String check(Level l,BlockPos root,Direction f,Player player,ItemStack item){var box=Ps01Geometry.bounds(root,f);if(box.minY<l.getMinBuildHeight()||box.maxY>l.getMaxBuildHeight())return "Not enough world height";for(var p:BlockPos.betweenClosed(BlockPos.containing(box.minX,box.minY,box.minZ),BlockPos.containing(box.maxX-1e-5,box.maxY-1e-5,box.maxZ-1e-5))){if(!l.hasChunkAt(p))return "Shelter area must be loaded";if(!l.getWorldBorder().isWithinBounds(p))return "Outside the world border";if(!BunkerVegetation.replaceable(l,p))return "Blocked: clear the complete shelter and door space";if(player!=null&&(!l.mayInteract(player,p)||!player.mayUseItemAt(p,Direction.UP,item)))return "You cannot build here";}
  for(var c:Ps01Geometry.SUPPORT){var p=Ps01Geometry.cell(root,f,c).below();if(!l.hasChunkAt(p)||!l.getBlockState(p).isFaceSturdy(l,p,Direction.UP))return "A flat solid foundation is required";}
  if(!l.getEntities((net.minecraft.world.entity.Entity)null,box,e->!e.isSpectator()&&!(e instanceof net.minecraft.world.entity.item.ItemEntity)&&!(e instanceof net.minecraft.world.entity.ExperienceOrb)).isEmpty())return "Blocked by a player, vehicle or other object";return "";
 }
 @Override protected boolean canPlace(BlockPlaceContext c,BlockState state){String why=check(c.getLevel(),c.getClickedPos(),state.getValue(Ps01Block.FACING),c.getPlayer(),c.getItemInHand());if(!why.isEmpty()&&c.getPlayer()!=null)c.getPlayer().displayClientMessage(Component.literal(why),true);return why.isEmpty()&&super.canPlace(c,state);}
 @Override protected boolean placeBlock(BlockPlaceContext c,BlockState state){var l=c.getLevel();var root=c.getClickedPos();var f=state.getValue(Ps01Block.FACING);var tx=new BunkerVegetation.Transaction(l);Ps01Block.MUTATING.set(true);try{if(!tx.clear(Ps01Geometry.bounds(root,f)))return false;for(int group=0;group<2;group++){var cells=group==0?Ps01Geometry.BODY:Ps01Geometry.DOOR;for(int i=0;i<cells.length;i++){var p=Ps01Geometry.cell(root,f,cells[i]);var s=group==0?state.setValue(Ps01Block.BODY_PART,i):AddonBlocks.PS01_DOOR.get().defaultBlockState().setValue(Ps01Block.FACING,f).setValue(Ps01Block.DOOR_PART,i);if(!tx.set(p,s)){tx.rollback();return false;}}}return true;}finally{Ps01Block.MUTATING.set(false);}}
 @Override public void appendHoverText(ItemStack s,Level l,List<Component> text,TooltipFlag flag){text.add(Component.translatable("ps01.description"));text.add(Component.translatable("ps01.controls"));text.add(Component.translatable("ps01.remove"));}
 @Override public void initializeClient(java.util.function.Consumer<net.minecraftforge.client.extensions.common.IClientItemExtensions> c){c.accept(new net.minecraftforge.client.extensions.common.IClientItemExtensions(){@Override public net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer getCustomRenderer(){return Ps01ItemRenderer.instance();}});}
}
